head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[image > M > getDataListInfo]<br/>Image 컴포넌트의 ref 속성에 바인딩된 DataCollection 정보를 반환합니다.",
    "validation" : [
        "ref 속성에 바인딩된 DataCollection 정보를 객체로 반환합니다.",
        "ref 속성을 설정하지 않았거나 잘못된 값이면 null 을 반환합니다.",
        "반환된 객체의 id 는 바인딩된 DataCollection 의 렌더링 ID 를 반환합니다.",
        "반환된 객체의 ref 는 ref 속성값을 반환합니다.",
        "반환값만으로는 바인딩된 DataCollection 이 DataList 인지 DataMap 인지 구분할 수 없습니다.",
    ]
}



scwin.onpageload = function () {
    // 정적 select1 초기값 설정 (ref : DataList 바인딩)
    con_ref.setValue("data:dlt_image.imgPath");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (scwin.target1) {
        scwin.target1.remove();
        scwin.target1 = null;
    }

    let cRef = con_ref.getValue();

    // DataList 바인딩 시 이미지가 바로 표시되도록 행 0 을 선택한 상태로 시작한다
    dlt_image.setRowPosition(0);

    let lblRef = (cRef === '') ? '미설정' : cRef;

    $c.gcm.createLabel('label="[현재] target1 : ref = ' + lblRef + '\n[절차] con_ref 값 변경 -> Target 재생성 -> getDataListInfo 반환값 확인 버튼 클릭\n[확인] 설정한 ref 값과 반환 객체를 한 줄에 나란히 출력하므로 두 값을 대조합니다\n[참고] 바인딩 값 : DataList 행 0 = /img/gif.gif, DataMap = /img/png.png 이므로 con_ref 전환 시 표시 이미지가 바뀝니다"', '', 'label1');

    // 조건 설정 (createCList 는 빈 값 property 를 제외하므로 미설정 시 ref 속성 자체가 선언되지 않는다)
    let properties = {
        ref : cRef,
    };

    let cList = $c.gcm.createCList(properties);

    // 공통 함수($c.gcm.createBasicImage)는 target 을 공통 모듈 scope 에 담으므로 직접 생성하여 페이지 scope 에 보관한다
    let grp_comp = $c.gcm.getTestGroup('');

    let strTarget = '<xf:image ' + $c.gcm.strNameSpace + ' ' + cList + '></xf:image>';

    scwin.target1 = await $p.dynamicCreate("target1", "image", strTarget, grp_comp);
}



// 반환값을 눈으로 구분 가능한 문자열로 변환 (null / undefined 와 객체 구분)
scwin.strInfo = function (info) {
    if (info === null)
        return "null";

    if (info === undefined)
        return "undefined";

    return "{ id : " + info.id + ", ref : " + info.ref + " }";
}



// validation 판정 출력
scwin.btn_getDataListInfo_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");

    let cRef = con_ref.getValue();
    let strRef = (cRef === '') ? "미설정" : cRef;

    let info = scwin.target1.getDataListInfo();

    // 설정한 ref 와 반환값을 한 줄에 나란히 출력해 모든 validation 을 값 자체로 판정한다
    //  - validation 1, 3, 4 : 반환 객체 전문 { id, ref } 와 줄 앞의 설정 ref 값을 대조
    //  - validation 2 : strInfo 가 null / undefined / 객체를 각각 다른 문자열로 출력하므로 값만으로 구분된다
    //                   (실측 : 미설정 -> null 로 가이드와 일치, 잘못된 값 -> undefined 로 가이드와 불일치)
    //  - validation 5 : DataList 바인딩과 DataMap 바인딩의 반환값이 모두 { id, ref } 두 키뿐이고
    //                   DataCollection 종류를 알려주는 값이 없다는 점이 두 케이스의 값 대비로 드러난다
    bottom.setReturnValue("ref = " + strRef + " -> 반환값 : " + scwin.strInfo(info));
};
